      SUBROUTINE FNDREF(KNAME)CC     FIND PREVIOUS REFERENCES TO DEFINED BEAM SUBLINECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM24A.CIN'CC     LOCAL VARIABLESC      CHARACTER*15    KNAME      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATAC-----------------------------------------------------------------------C      IF (NEL .EQ. 0) GO TO 200      DO 20 NN = 1, NEL      IEL = ISTOR(NN)      NTYPE = IDATA(IEL)      IF (KNAME .NE. LABEL(NN)) GO TO 20      IF (NTYPE .NE. 24) GO TO 20      IREF = IDATA(IEL+1)      IF (IREF .NE. 3 .AND. IREF .NE. 4) GO TO 20      IADD = JDEF + 1      IADR = IEL + IADD      LAKE = NUM      DATA(IADR) = FAKE      TIE(IADR) = 100   20 CONTINUE  200 RETURN      END